{"file_path":"src/policies.js","content":"/**
 * Token buckets and sliding windows, each keeping one independent state per
 * key. Every count involved (capacities, ticks, ...) is a `BigInt` so a
 * bucket's fractional refill never loses precision and neither representation
 * is bounded by the size of a JS number.
 */

/**
 * A token bucket. Tokens are tracked in units of `1/per` of a token so that
 * "`refill` tokens for every `per` ticks" accumulates exactly: `n` elapsed
 * ticks add `refill * n` units, and one whole token is `per` units.
 */
export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityUnits = capacity * per
    this.states = new Map() // key -> { units, tick }
  }

  advance(key, tick) {
    const state = this.states.get(key)
    if (!state) {
      this.states.set(key, { units: this.capacityUnits, tick })
      return
    }
    const elapsed = tick - state.tick
    if (elapsed > 0n) {
      const units = state.units + this.refill * elapsed
      state.units = units > this.capacityUnits ? this.capacityUnits : units
      state.tick = tick
    }
  }

  allow(key) {
    return this.states.get(key).units >= this.per
  }

  record(key) {
    this.states.get(key).units -= this.per
  }
}

/**
 * A sliding window. Each key remembers the ticks of the requests it recorded,
 * oldest first, so advancing only ever needs to drop from the front.
 */
export class Window {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map() // key -> ticks[]
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (!ticks) {
      ticks = []
      this.states.set(key, ticks)
    }
    const threshold = tick - this.span
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= threshold) drop++
    if (drop > 0) ticks.splice(0, drop)
  }

  allow(key) {
    return this.states.get(key).length < this.limit
  }

  record(key, tick) {
    this.states.get(key).push(tick)
  }
}
"}

