{"file_path":"src/parser.js","content":"/**
 * Parses a limiter file into the runtime model `simulate.js` replays: the
 * declared policies, the routes over them, and the ordered events. Every
 * validation failure throws a `ParseError` carrying the 1-based line number
 * and the exact reason text the CLI reports.
 */
import { ParseError } from './errors.js'
import { Bucket, Window } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

function parseUint(text, field, min, line) {
  if (!UINT_RE.test(text)) throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  const value = BigInt(text)
  if (value < min) throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  return value
}

function checkName(text, line) {
  if (!NAME_RE.test(text)) throw new ParseError(line, `invalid policy name ${text}`)
}

function checkPrefix(text, line) {
  if (!NAME_RE.test(text)) throw new ParseError(line, `invalid route prefix ${text}`)
}

function checkKey(text, line) {
  if (!NAME_RE.test(text)) throw new ParseError(line, `invalid key ${text}`)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map() // name -> Bucket | Window
  const routes = [] // { prefix, policyNames }
  const events = [] // { tick, key }
  let hasEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const line = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const rest = tokens.slice(1)

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (hasEvent) throw new ParseError(line, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (rest.length !== 4) throw new ParseError(line, 'expected bucket <name> <capacity> <refill> <per>')
      const [name, capacityText, refillText, perText] = rest
      checkName(name, line)
      const capacity = parseUint(capacityText, 'capacity', 1n, line)
      const refill = parseUint(refillText, 'refill', 0n, line)
      const per = parseUint(perText, 'per', 1n, line)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      policies.set(name, new Bucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (rest.length !== 3) throw new ParseError(line, 'expected window <name> <limit> <span>')
      const [name, limitText, spanText] = rest
      checkName(name, line)
      const limit = parseUint(limitText, 'limit', 0n, line)
      const span = parseUint(spanText, 'span', 1n, line)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      policies.set(name, new Window(limit, span))
    } else if (directive === 'route') {
      if (rest.length < 2) throw new ParseError(line, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      checkPrefix(prefix, line)
      for (const name of policyNames) {
        checkName(name, line)
        if (!policies.has(name)) throw new ParseError(line, `unknown policy ${name}`)
      }
      if (routes.some((r) => r.prefix === prefix)) throw new ParseError(line, `prefix ${prefix} is routed twice`)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (rest.length !== 2) throw new ParseError(line, 'expected event <tick> <key>')
      const [tickText, key] = rest
      const tick = parseUint(tickText, 'tick', 0n, line)
      checkKey(key, line)
      if (lastTick !== null && tick < lastTick) throw new ParseError(line, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      hasEvent = true
      events.push({ tick, key })
    } else {
      throw new ParseError(line, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

