{"file_path":"src/simulate.js","content":"/**
 * Replays parsed events against their routed policies and reports each
 * event's verdict alongside the running per-key and total tallies.
 */

/**
 * Finds the route whose prefix is longest among those the key starts with,
 * or `undefined` when no route matches.
 */
function findRoute(routes, key) {
  let best
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (!best || route.prefix.length > best.prefix.length)) best = route
  }
  return best
}

/**
 * Runs every event in order and returns `{ verdicts, perKey, total }`, where
 * `verdicts` is one entry per event (`{ tick, key, allowed, deniedBy }`),
 * `perKey` maps each key that saw an event to its `{ allowed, denied }`
 * tally (insertion order of first appearance), and `total` is the same
 * shape summed over every event.
 */
export function simulate({ policies, routes, events }) {
  const verdicts = []
  const perKey = new Map()
  const total = { allowed: 0, denied: 0 }

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    const members = route ? route.policyNames.map((name) => policies.get(name)) : []

    for (const policy of members) policy.advance(key, tick)

    let deniedBy = null
    for (let i = 0; i < members.length; i++) {
      if (!members[i].allow(key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }

    const allowed = deniedBy === null
    if (allowed) for (const policy of members) policy.record(key, tick)

    verdicts.push({ tick, key, allowed, deniedBy })

    if (!perKey.has(key)) perKey.set(key, { allowed: 0, denied: 0 })
    const tally = perKey.get(key)
    if (allowed) {
      tally.allowed++
      total.allowed++
    } else {
      tally.denied++
      total.denied++
    }
  }

  return { verdicts, perKey, total }
}
"}

