{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { parse } from './parser.js'
import { simulate } from './simulate.js'
import { ParseError } from './errors.js'

const mode = process.argv[2]
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')

let model
try {
  model = parse(input)
} catch (err) {
  if (err instanceof ParseError) {
    process.stderr.write(`error: line ${err.line}: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}

const { verdicts, perKey, total } = simulate(model)

const lines = []
if (mode === 'replay') {
  for (const v of verdicts) {
    lines.push(v.allowed ? `${v.tick} ${v.key} allow` : `${v.tick} ${v.key} deny ${v.deniedBy}`)
  }
} else {
  for (const key of [...perKey.keys()].sort()) {
    const t = perKey.get(key)
    lines.push(`${key} allowed=${t.allowed} denied=${t.denied}`)
  }
  lines.push(`total allowed=${total.allowed} denied=${total.denied}`)
}

process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
process.exit(0)
"}

